import {indicators,numberLabel,periodLabel} from './observatorio-economy-data.mjs';
const context={
 dolar:['Un aumento significa que se necesitan más pesos por dólar; una caída, menos pesos. Esto cambia el equivalente en pesos de pagos denominados en dólares.','Para explicar sus movimientos conviene contrastar tasas de interés, comercio exterior y condiciones internacionales. La serie por sí sola no identifica la causa.'],
 uf:['El cambio de la UF modifica el monto en pesos de contratos expresados en esta unidad, manteniendo constante su cantidad de UF.','Su trayectoria corresponde a un reajuste, no a oferta y demanda de un activo negociado. Revisa el IPC y las condiciones de cada contrato.'],
 ipc:['Un IPC mensual positivo indica un aumento promedio de la canasta frente al mes anterior; uno negativo, una disminución. No describe por igual el gasto de todos los hogares.','Para evaluar persistencia se necesitan las divisiones del IPC y su evolución a doce meses. Un mes aislado no establece una tendencia anual.'],
 tpm:['La TPM orienta las condiciones monetarias; su transmisión a las tasas de depósitos y créditos no es instantánea ni idéntica.','El Banco Central evalúa inflación proyectada y actividad al tomar decisiones. El nivel de la tasa, por sí solo, no permite anticipar la próxima reunión.'],
 cobre:['La referencia expresa dólares por libra. Su cambio altera el valor bruto de una misma cantidad de cobre; los ingresos efectivos también dependen de volúmenes, costos y contratos.','Para explicar el precio se requieren datos adicionales de producción, demanda e inventarios. Aquí no se atribuyen los movimientos a noticias no contrastadas.'],
 imacec:['Una variación anual positiva indica más actividad que en el mismo mes del año anterior; una negativa, menos. No equivale al crecimiento frente al mes inmediatamente anterior.','Para evaluar el impulso reciente se requiere la serie desestacionalizada y el desglose sectorial. Los efectos de base pueden modificar la comparación anual.']
};
export function technicalMetrics(series){
 const rows=series.filter(r=>!r.carried&&Number.isFinite(r.value)).slice().sort((a,b)=>a.date.localeCompare(b.date));
 const values=rows.map(r=>r.value),mean=n=>values.length>=n?values.slice(-n).reduce((a,b)=>a+b,0)/n:null;
 let rsi=null;if(values.length>=15){const last=values.slice(-15),changes=last.slice(1).map((v,i)=>v-last[i]);const gains=changes.reduce((s,v)=>s+Math.max(v,0),0),losses=changes.reduce((s,v)=>s+Math.max(-v,0),0);rsi=gains+losses===0?50:losses===0?100:100-100/(1+gains/losses);}
 return {count:rows.length,first:rows[0],last:rows.at(-1),min:values.length?Math.min(...values):null,max:values.length?Math.max(...values):null,sma20:mean(20),sma50:mean(50),rsi};
}
export function fundamentalReading(id,d){
 const previous=d.series.filter(r=>r.date<(d.date.length===7?d.date+'-01':d.date)).at(-1);
 const value=numberLabel(d.value,id),date=periodLabel(d.date);
 const movement=d.value>0?'aumentó':d.value<0?'disminuyó':'no varió';
 if(id==='ipc')return `En ${date}, el nivel de precios ${movement} ${numberLabel(Math.abs(d.value),id)} frente al mes anterior.${Number.isFinite(d.annual)?` La variación a doce meses fue ${numberLabel(d.annual,id)}; no debe confundirse con la mensual.`:''}`;
 if(id==='imacec')return `En ${date}, la actividad ${movement} ${numberLabel(Math.abs(d.value),id)} respecto del mismo mes del año anterior. Esta tasa no mide el cambio frente al mes previo.`;
 if(id==='tpm')return `La referencia publicada al ${date} es ${value}.${d.effectiveSince?` El nivel se mantiene desde ${periodLabel(d.effectiveSince)}.`:''} El histórico recoge cambios de tasa, no todas las reuniones: puede haber decisiones de mantenerla sin un nuevo punto.`;
 if(!previous)return `La referencia al ${date} es ${value}.`;
 const delta=d.value-previous.value,verb=delta>0?'subió':delta<0?'bajó':'se mantuvo';
 return `Al ${date}, la referencia ${verb}${delta!==0?' '+numberLabel(Math.abs(delta),id):''} respecto del ${periodLabel(previous.date)} (${numberLabel(previous.value,id)}). ${id==='dolar'?'Por cada dólar, ese es el cambio del equivalente en pesos.':id==='uf'?'Para una obligación de 100 UF, el cambio del equivalente en pesos es '+numberLabel(delta*100,id)+'.':'Es una comparación de precios de referencia; no mide por sí sola ingresos mineros ni rentabilidad.'}`;
}
export function analysisHtml(id,d,rows,esc){if(!d)return '';const m=technicalMetrics(rows),full=technicalMetrics(d.series.filter(r=>r.date<=(d.date.length===7?d.date+'-01':d.date))),market=['dolar','cobre'].includes(id),fmt=v=>numberLabel(v,id),num=v=>new Intl.NumberFormat('es-CL',{maximumFractionDigits:2}).format(v),delta=m.last&&m.first?m.last.value-m.first.value:null;
 const source=`<a href="${esc(d.source.url)}" target="_blank" rel="noopener noreferrer">${esc(d.source.name)} ↗</a>`;
 const facts=`Último dato: ${fmt(d.value)} · ${periodLabel(d.date)}.${id==='ipc'&&Number.isFinite(d.annual)?` Variación en doce meses: ${fmt(d.annual)}.`:''}`;
 return `<section class="panel econ-analysis" aria-label="Análisis de ${esc(indicators[id].name)}"><h2>Conoce ${esc(indicators[id].name)}</h2><div class="econ-analysis-grid"><section><span class="eyebrow">INFORMACIÓN</span><h3>Qué estás consultando</h3><p>${esc(indicators[id].explanation)}</p><p>${esc(facts)}</p><p>Fuente de los datos: ${source}.</p></section><section><span class="eyebrow">ANÁLISIS FUNDAMENTAL</span><h3>Lectura del último dato</h3><p class="econ-reading">${esc(fundamentalReading(id,d))}</p><p>Base de esta lectura: ${source} · ${esc(periodLabel(d.date))}.</p><h4>Contexto fundamental</h4><p>${esc(context[id][0])}</p><p>${esc(context[id][1])}</p><p class="muted">Lectura de Atlas: contexto económico, sin atribuir causas a la variación observada.</p>${['ipc','tpm'].includes(id)?`<a href="${id==='ipc'?'https://www.ine.gob.cl/estadisticas-por-tema/precios-e-inflacion/indice-de-precios-al-consumidor':'https://www.bcentral.cl/web/banco-central/areas/politica-monetaria'}" target="_blank" rel="noopener noreferrer">Marco y metodología oficial ↗</a>`:''}</section><section><span class="eyebrow">ANÁLISIS TÉCNICO</span><h3>${market?'Tendencia de la referencia':'Evolución de la serie'}</h3>${m.count?`<p>En el período seleccionado: mínimo ${fmt(m.min)}, máximo ${fmt(m.max)}. ${m.count>1?`Cambio entre ${periodLabel(indicators[id].frequency==='monthly'?m.first.date.slice(0,7):m.first.date)} y ${periodLabel(indicators[id].frequency==='monthly'?m.last.date.slice(0,7):m.last.date)}: ${num(delta)} ${indicators[id].symbol==='%'?'puntos porcentuales':esc(indicators[id].unit)}.`:'Una observación no permite medir variación.'}</p>`:'<p>Sin cambios de tasa registrados en el período seleccionado.</p>'}${market?`<dl><dt>Media de 20 observaciones</dt><dd>${full.sma20===null?'Requiere 20 observaciones':fmt(full.sma20)}</dd><dt>Media de 50 observaciones</dt><dd>${full.sma50===null?'Requiere 50 observaciones':fmt(full.sma50)}</dd><dt>RSI simple · 14 cambios</dt><dd>${full.rsi===null?'Requiere 15 observaciones':num(full.rsi)+' / 100'}</dd></dl>${full.sma20!==null?`<p>El último valor está ${d.value>full.sma20?'por encima de':d.value<full.sma20?'por debajo de':'en'} su media de 20 observaciones.</p>`:''}<p class="muted">Medias y RSI simple calculados al ${periodLabel(full.last?.date)} sobre las últimas observaciones publicadas, independientemente del zoom. No son datos intradía ni señales de compra o venta.</p>`:`<p>${id==='tpm'?`Tasa vigente: ${fmt(d.value)}${d.effectiveSince?' desde '+periodLabel(d.effectiveSince):''}. Las líneas entre cambios no representan nuevas observaciones. El histórico no enumera las reuniones que mantienen la tasa.`:id==='uf'?'La UF es una unidad reajustable: RSI y señales de negociación no son adecuados para interpretarla.':'Se comparan tasas publicadas en puntos porcentuales. No se aplican señales de negociación a esta serie macroeconómica.'}</p>`}<details><summary>Cómo se calcula</summary><p>El rango y el cambio usan solo observaciones publicadas del período, excluyendo puntos dibujados para mantener la TPM. En la TPM el rango se refiere a los cambios registrados, no a todas las tasas vigentes durante la ventana. Las medias son aritméticas. El RSI simple usa las ganancias y pérdidas medias de los últimos 14 cambios: 100 − 100 / (1 + ganancias / pérdidas); sin cambios vale 50. No utiliza el suavizado de Wilder. Estos cálculos describen el pasado y no predicen el siguiente valor.</p></details><p class="muted">Cálculo de Atlas sobre ${source}.${d.stale?' Datos conservados tras una actualización fallida.':''}</p></section></div></section>`;
}
